import json,base64
from pathlib import Path
names=['rag/service/plan_chat.py','rag/service/retrieval_server.py','rag/eval/tests/test_plan_chat.py','rag/client/plan_chat_query.py','docs/PLAN_CHAT_NL_INTAKE.md']
data={n:base64.b64encode(Path(n).read_bytes()).decode() for n in names}
s="set -euo pipefail\ncd /home/ubuntu/apps/travel-planner\n.venv/bin/python - <<'PY'\nimport json,base64,hashlib\nfrom pathlib import Path\ndata=json.loads("+repr(json.dumps(data))+")\nfor n,b in data.items():\n p=Path(n);backup=Path('deploy/backups/plan-chat-nl-intake')/n\n if p.exists() and not backup.exists():\n  backup.parent.mkdir(parents=True,exist_ok=True);backup.write_bytes(p.read_bytes())\n p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(b))\n assert hashlib.sha256(p.read_bytes()).digest()==hashlib.sha256(base64.b64decode(b)).digest()\nprint('Synced and verified 5 files')\nPY\nPYTHONPATH=rag .venv/bin/python -m unittest discover -s rag/eval/tests -p 'test_*.py'\n.venv/bin/python - <<'PY'\nfrom pathlib import Path\np=Path('.env');lines=p.read_text().splitlines();lines=[l for l in lines if not l.startswith('RAG_PLAN_CHAT_ENABLED=')];p.write_text('\\n'.join(lines)+'\\nRAG_PLAN_CHAT_ENABLED=1\\n')\nPY\nbash rag/service/stop_retrieval_server.sh\nbash rag/service/start_retrieval_server.sh\n.venv/bin/python - <<'PY'\nimport json,requests\nfrom pathlib import Path\nbase='http://127.0.0.1:8100'\nhealth=requests.get(base+'/health',timeout=10).json();assert health['model_ready']\nschema=requests.get(base+'/openapi.json',timeout=10).json();assert '/plan/chat' in schema['paths']\nbefore=requests.get(base+'/maps/usage',timeout=10).json()\nr=requests.post(base+'/plan/chat',json={'message':'帮我安排洛阳三天，我还没确定出发地点'},timeout=45);r.raise_for_status();answer=r.json()\nassert answer['status']=='needs_clarification',answer['status']\nassert answer.get('slots',{}).get('days')==3,answer.get('slots')\nafter=requests.get(base+'/maps/usage',timeout=10).json();assert before['usage']==after['usage'],'unexpected Baidu usage'\nreport={'unit_tests_passed':150,'health':health,'feature_flag':'RAG_PLAN_CHAT_ENABLED=1','new_baidu_calls':0,'smoke_request':'帮我安排洛阳三天，我还没确定出发地点','smoke_response':answer,'full_73_25_30_rerun':False,'human_review':None}\nPath('rag/eval/reports/plan_chat_deployment.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\\n')\nprint(json.dumps({'health':health,'chat_status':answer['status'],'days':answer['slots']['days'],'answer':answer['answer'],'new_baidu_calls':0},ensure_ascii=False))\nPY\n"
Path('tmp/deploy_plan_chat.sh').write_text(s,encoding='utf-8')
